<?php

declare(strict_types=1);

/*
 * Validates the schema files, the shipped config examples, the legacy
 * fixtures, and manifests freshly generated by the library against
 * docs/schemas. Exits non-zero on any problem. Usage: composer schemas
 */

use ImagePuzzle\Config\PuzzleConfig;
use ImagePuzzle\PuzzleGenerator;
use ImagePuzzle\Tools\SchemaValidator;

require dirname(__DIR__) . '/vendor/autoload.php';

/**
 * @param array<mixed> $errors
 */
function printReport(string $subject, array $errors): bool
{
    if ($errors === []) {
        echo "ok    {$subject}\n";

        return true;
    }
    echo "FAIL  {$subject}\n";
    foreach ($errors as $error) {
        echo '      ' . (is_string($error) ? $error : json_encode($error)) . "\n";
    }

    return false;
}

$root = dirname(__DIR__);
$validator = SchemaValidator::forRepository();
$failures = 0;
$report = static function (string $subject, array $errors) use (&$failures): void {
    if (printReport($subject, $errors)) {
        return;
    }
    $failures++;
};

$report('schema files ($id and syntax)', $validator->checkSchemaFiles());

$configs = glob($root . '/config/*.json');
foreach ($configs === false ? [] : $configs as $file) {
    $report('config/' . basename($file), $validator->validateFile($file));
}
$report('tests/fixtures/config/legacy-v1.json (v1)', $validator->validateFile($root . '/tests/fixtures/config/legacy-v1.json', 'v1/puzzle-config.schema.json'));

// Freshly generated manifests, one per topology.
$tmp = sys_get_temp_dir() . '/image-puzzle-schemas-' . bin2hex(random_bytes(6));
mkdir($tmp, 0700);
try {
    $source = $tmp . '/source.png';
    $image = imagecreatetruecolor(96, 72);
    imagefilledrectangle($image, 0, 0, 95, 71, (int) imagecolorallocate($image, 40, 120, 200));
    imagepng($image, $source);
    foreach (['rect' => [3, 4], 'hex' => [3, 3], 'triangle' => [2, 3]] as $topology => [$rows, $cols]) {
        $config = PuzzleConfig::fromArray([
            'configVersion' => 2,
            'rows' => $rows,
            'cols' => $cols,
            'edge' => ['type' => 'jigsaw'],
            'geometry' => ['seed' => 3, 'samples' => 2, 'topology' => $topology],
        ]);
        $result = PuzzleGenerator::generateAndExport(
            $source,
            "{$tmp}/{$topology}",
            $rows,
            $cols,
            $config->edgeStyle(),
            $config->exportOptions(),
            geometry: $config->geometryOptions(),
        );
        $report("generated manifest ({$topology})", $validator->validateFile($result->getManifestPath(), 'v2/manifest.schema.json'));
        $report("normalised config ({$topology})", $validator->validate($config->toArray(), 'v2/puzzle-config.schema.json'));
    }
} finally {
    $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($tmp, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::CHILD_FIRST);
    foreach ($it as $entry) {
        if (!$entry instanceof SplFileInfo) {
            continue;
        }
        $entry->isDir() && !$entry->isLink() ? rmdir($entry->getPathname()) : unlink($entry->getPathname());
    }
    rmdir($tmp);
}

// Game definitions, boards, states and actions from the conformance fixtures.
$fixtures = glob($root . '/conformance/mode-*.json');
if ($fixtures === false || $fixtures === []) {
    $report('conformance fixtures', ['none found; run composer conformance']);
}
/**
 * @return list<mixed>
 */
function listAt(mixed $value, string $key): array
{
    $list = is_array($value) ? ($value[$key] ?? null) : null;

    return is_array($list) && array_is_list($list) ? $list : [];
}

foreach ($fixtures === false ? [] : $fixtures as $file) {
    $name = basename($file);
    $json = (string) file_get_contents($file);
    // Objects keep {} distinct from [] for the definition; arrays are easier to walk.
    $objects = json_decode($json, false, 64, JSON_THROW_ON_ERROR);
    $doc = json_decode($json, true, 64, JSON_THROW_ON_ERROR);
    if (!$objects instanceof stdClass || !is_array($doc) || !is_array($doc['definition'] ?? null) || !is_string($doc['definition']['kind'] ?? null)) {
        $report($name, ['not a mode fixture']);
        continue;
    }
    $report("{$name} definition", $validator->validateObjects($objects->definition ?? null, 'game/v1/definition.schema.json'));
    $errors = [];
    $boards = [$doc['solved'] ?? null];
    foreach (listAt($doc, 'scrambles') as $scramble) {
        $boards[] = is_array($scramble) ? ($scramble['board'] ?? null) : null;
    }
    foreach (listAt($doc, 'cases') as $case) {
        foreach (listAt($case, 'steps') as $step) {
            if (is_array($step) && isset($step['board'])) {
                $boards[] = $step['board'];
            }
        }
    }
    foreach ($boards as $board) {
        array_push($errors, ...$validator->validate($board, 'game/v1/board.schema.json#/$defs/' . $doc['definition']['kind']));
    }
    foreach (listAt($doc, 'legalActions') as $action) {
        array_push($errors, ...$validator->validate($action, 'game/v1/action.schema.json'));
    }
    $report("{$name} boards and actions", $errors);
    $definition = ImagePuzzle\Game\GameDefinition::fromJson((string) json_encode($objects->definition ?? null));
    $state = (new ImagePuzzle\Game\GameEngine())->start($definition);
    $report("{$name} initial state", $validator->validate($state->toArray(), 'game/v1/state.schema.json'));
}

// Example definitions played by the browser player (examples/player).
$examples = array_merge(glob($root . '/examples/player/assets/*.json') ?: [], glob($root . '/examples/player/assets/*/definition.json') ?: []);
foreach ($examples as $file) {
    $name = substr($file, strlen($root) + 1);
    $json = (string) file_get_contents($file);
    $report($name, $validator->validateObjects(json_decode($json, false, 64, JSON_THROW_ON_ERROR), 'game/v1/definition.schema.json'));
    try {
        ImagePuzzle\Game\GameDefinition::fromJson($json);
        $report("{$name} (PHP)", []);
    } catch (Throwable $e) {
        $report("{$name} (PHP)", [$e->getMessage()]);
    }
}

// Build configurations as BuildConfiguration writes them, one per mode.
foreach (ImagePuzzle\Game\Modes::available() as $kind) {
    $custom = ImagePuzzle\Game\BuildConfiguration::fromArray([
        'format' => ImagePuzzle\Game\BuildConfiguration::FORMAT,
        'version' => 1,
        'kind' => $kind->value,
        'preset' => 'custom',
        'custom' => array_fill_keys(array_slice(ImagePuzzle\Game\GameFactory::customKeys($kind), 0, 2), 2),
        'seed' => $kind === ImagePuzzle\Game\GameKind::Jigsaw ? ImagePuzzle\GeometryOptions::MAX_SEED : ImagePuzzle\Game\Prng::MAX_SEED,
        'crop' => ['x' => 0, 'y' => 3, 'width' => 40, 'height' => 30],
    ]);
    $preset = new ImagePuzzle\Game\BuildConfiguration($kind, 'hard', [], 1);
    $report("build configuration ({$kind->value})", [
        ...$validator->validate($custom->toArray(), 'game/v1/build-config.schema.json'),
        ...$validator->validate($preset->toArray(), 'game/v1/build-config.schema.json'),
    ]);
}

echo $failures === 0 ? "\nAll schema checks passed.\n" : "\n{$failures} schema check(s) failed.\n";
exit($failures === 0 ? 0 : 1);
